const eps = (x) => Math.round((x + Number.EPSILON) * 100) / 100;
const plain = (x) => Math.round(x * 100) / 100;
let badEps = 0, badPlain = 0;
for (let n = -100000; n <= 100000; n++) {
  const x = n / 1000; // exact decimal thousandths
  const expectedCents = Math.round(n / 10); // x.5 is exact in binary; half-up
  if (Math.abs(eps(x) - expectedCents / 100) > 1e-9) badEps++;
  if (Math.abs(plain(x) - expectedCents / 100) > 1e-9) badPlain++;
}
console.log('eps mismatches:', badEps, '/ plain mismatches:', badPlain);"

